package com.jnapanam.sportszone.content.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="contact_inquiries")public class ContactInquiry{@Id private UUID id;@Column(nullable=false,length=120)private String name;@Column(nullable=false,length=180)private String email;@Column(length=20)private String mobile;@Column(nullable=false,length=180)private String subject;@Column(nullable=false,columnDefinition="TEXT")private String message;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private InquiryStatus status;@Column(name="admin_note",length=500)private String adminNote;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="resolved_at")private Instant resolvedAt;protected ContactInquiry(){}public ContactInquiry(String n,String e,String m,String s,String msg){id=UUID.randomUUID();name=n.trim();email=e.trim().toLowerCase();mobile=clean(m);subject=s.trim();message=msg.trim();status=InquiryStatus.NEW;createdAt=Instant.now();}public void status(InquiryStatus s,String note){status=s;adminNote=clean(note);resolvedAt=s==InquiryStatus.RESOLVED?Instant.now():null;}public UUID getId(){return id;}public String getName(){return name;}public String getEmail(){return email;}public String getMobile(){return mobile;}public String getSubject(){return subject;}public String getMessage(){return message;}public InquiryStatus getStatus(){return status;}public String getAdminNote(){return adminNote;}public Instant getCreatedAt(){return createdAt;}public Instant getResolvedAt(){return resolvedAt;}private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
